// Memo 1 of E11: "Does NIS2 apply to us?" Directive (EU) 2022/2555 read at the original (Art. 2, 3, 20, 21, 23, 26, 34, Annexes I and II),
// the SME Recommendation for the size classes, and the national laws of Germany (BSIG, 6 December 2025) and Austria (NISG 2026, 1 October 2026).
import { L, S, BUSINESS_Q, buildDoc, has } from './shared.mjs';

// Sector options: which annex of the directive they belong to.
